/* Keep advanced controls available while making the default path automatic. */
(()=>{
 const form=$('entryform'),ids=['teacher','student','studentSignDate','version','nature','rule','qty','ratio','project','paid','override','reason','condition','note','signupHours','signupProjects','fullPaid','advisor','trialDate','enrolledCourse'];
 const labels=Object.fromEntries(ids.map(id=>[id,$(id).closest('label')]));
 form.innerHTML=`<div class="manual-layout"><div><div class="form manual-fields" id="manualCore"></div><div class="form manual-fields" id="manualContext"></div></div><div class="manual-price"><div class="actions" style="margin:0"><strong>自动价格方案</strong><span id="manualStatus" class="pill neutral">待填写</span></div><p id="manualVersion" class="muted"></p><p id="versionPolicyHint" class="muted"></p><p id="manualPlan"></p><p id="manualFormula" class="muted"></p><strong id="manualPrice">—</strong><p id="estimate" class="muted"></p><div class="form" id="manualAdjustment"></div><p id="rulenote" class="muted"></p></div></div><details id="manualAdvanced" class="manual-advanced"><summary>高级核对与补充信息</summary><p class="muted">自动匹配不适用时，可手动选规则。</p><label class="check"><input id="manualRuleMode" type="checkbox">手动指定价格方案</label><div class="form" id="manualRuleControls"></div><div class="form" id="manualOther"></div><div class="form" id="manualSignupMeta"></div></details><div class="actions"><button class="primary" id="manualSave" type="submit">保存绩效记录</button><button id="cancel" type="button">清空 / 取消编辑</button></div>`;
 const add=(holder,id)=>$(holder).append(labels[id]);
 for(const id of ['teacher','student','studentSignDate'])add('manualCore',id);
 $('manualCore').insertAdjacentHTML('beforeend',`<label id="manualCountryLabel">申请国家<input id="manualCountry" list="manualCountries" placeholder="如：英国、美国、香港"><datalist id="manualCountries"><option>英国</option><option>美国</option><option>意大利、法国</option><option>香港</option><option>韩国</option><option>中国</option></datalist></label><label id="manualDegreeLabel">学生学历<input id="manualDegree" list="manualDegrees" placeholder="本科 / 研究生"><datalist id="manualDegrees"><option>本科</option><option>研究生</option></datalist></label><label>学生套餐<input id="manualPackage" placeholder="如：Top3、保研A、25课时" list="manualPackages"><datalist id="manualPackages"><option>Top1</option><option>Top3</option><option>Top5</option><option>Top8</option><option>非VIP</option><option>单作品集</option><option>保研A</option><option>保研B</option><option>保研C</option><option>保研D</option></datalist></label><label id="manualMajorLabel">专业 / 科系<input id="manualMajor" placeholder="如：服装设计、工业设计"></label><label>本次产出<input id="manualType" list="manualTypes" placeholder="如：项目、排版指导、辅助签约" required><datalist id="manualTypes"><option>项目</option><option>软件基础课</option><option>排版指导</option><option>SP</option><option>视频</option><option>面试辅导</option><option>辅助签约</option><option>自产转介绍</option></datalist></label>`);
 add('manualCore','project');for(const id of ['qty','fullPaid','signupHours','signupProjects','paid'])add('manualContext',id);
 add('manualAdjustment','override');add('manualAdjustment','reason');
 for(const id of ['version','rule'])add('manualRuleControls',id);$('manualRuleControls').insertAdjacentHTML('beforeend','<label class="wide">核对说明<input id="manualRuleReason" placeholder="手动指定方案时填写确认依据"></label>');
 for(const id of ['nature','ratio','condition','note'])add('manualOther',id);for(const id of ['advisor','trialDate','enrolledCourse'])add('manualSignupMeta',id);
 $('version').disabled=true;$('rule').required=false;$('override').min='0';
 $('override').closest('label').firstChild.textContent='调整金额（选填）';$('reason').closest('label').firstChild.textContent='调整原因';
 let autoVersion='',inputType='';
 function rawInput(){return {teacher:$('teacher').value.trim(),student:$('student').value.trim(),signDate:$('studentSignDate').value,nature:$('nature').value,country:$('manualCountry').value.trim(),degree:$('manualDegree').value.trim(),package:$('manualPackage').value.trim(),major:$('manualMajor').value.trim(),discipline:$('manualMajor').value.trim(),type:$('manualType').value.trim(),project:$('project').value.trim(),progress:$('ratio').value,quantity:$('qty').value,hours:$('qty').value,note:$('note').value,fullPaid:$('fullPaid').value,signupHours:$('signupHours').value,signupProjects:$('signupProjects').value,advisor:$('advisor').value,trialDate:$('trialDate').value,enrolledCourse:$('enrolledCourse').value}}
 formEntry=function(){const previous=editing?state.entries.find(e=>e.id===editing):undefined;return ManualQuote.evaluate(rawInput(),state.staff,state.staffRules||{},{previous,month:$('month').value,ruleOverride:$('manualRuleMode').checked?$('rule').value:'',manualReason:$('manualRuleReason').value.trim(),paid:$('paid').value,override:$('override').value===''?null:Number($('override').value),reason:$('reason').value,condition:$('condition').value})};
 function show(id,yes){$(id).closest('label').classList.toggle('hidden',!yes)}
 function rulesFor(version,chosen){if(autoVersion!==version){autoVersion=version;$('version').value=version;$('rule').innerHTML='<option value="">请选择核实后的价格方案</option>'+RULES.filter(r=>r.version===version).map(r=>`<option value="${esc(r.id)}">${esc(r.group+' · '+r.item+' · '+r.tier+' ｜ '+r.rate+'元/'+r.unit)}</option>`).join('')}if(chosen!==undefined)$('rule').value=chosen||'';$('rule').required=false}
 estimate=function(){const raw=rawInput(),previous=editing?state.entries.find(e=>e.id===editing):undefined,auto=ManualQuote.evaluate(raw,state.staff,state.staffRules||{},{previous,month:$('month').value});
  const prior=$('rule').value;rulesFor(auto.version,$('manualRuleMode').checked&&autoVersion===auto.version?prior:auto.rule);
  const e=formEntry(),r=ruleBy(e.rule),c=calculate(e),signup=/辅助签约/.test(raw.type),referral=/自产转介绍/.test(raw.type),hourly=r?.unit==='小时'||/软件|基础课|课时|思维|绘画/.test(raw.type);
  show('qty',!signup);$('qty').closest('label').firstChild.textContent=referral?'学生报名签约金额（元）':hourly?'当月实际授课小时':'本次结算数量';show('fullPaid',signup);show('signupHours',signup&&e.version==='老汉艺版本');show('signupProjects',signup&&e.version==='老汉艺版本');show('paid',referral);show('project',!signup&&!referral&&!hourly);
  $('manualDegreeLabel').classList.toggle('hidden',signup||referral);$('manualMajorLabel').classList.toggle('hidden',signup||referral);$('manualCountryLabel').classList.toggle('hidden',referral);$('manualSignupMeta').classList.toggle('hidden',!signup);$('manualRuleControls').classList.toggle('hidden',!$('manualRuleMode').checked);
  const selected=StaffVersionPolicy.resolve(raw.teacher,raw.signDate,state.staff,state.staffRules||{});$('manualVersion').textContent=raw.teacher?(raw.teacher+' · '+e.version+(!previous&&!state.staff[raw.teacher]&&!selected.configured?'（未设置员工版本，暂按常规版）':'')):'选择老师后自动读取绩效版本';$('versionPolicyHint').textContent=selected.configured?(selected.issue||selected.reason):'';
  $('manualPlan').textContent=r?r.group+' · '+r.item+' · '+r.tier:(auto.importIssue||auto.excludedReason||'填写学生情况、套餐和本次产出后，自动匹配价格。');
  $('manualStatus').textContent=r?c.status:(auto.excludedReason?'无绩效':'待匹配');$('manualStatus').className='pill '+(r?performanceStatusClass(c.status):auto.excludedReason?'neutral':'warn');
  let formula='';if(r){if(r.item==='自产转介绍')formula='签约金额 × 3%，每名学生上限3000元，再扣除此前已发金额';else formula=money(r.rate)+'元 / '+r.unit+(e.signupShareCount>1?' ÷ '+e.signupShareCount+'位老师':!signup?' × '+e.qty+' '+r.unit:'');if(e.ratio!==1)formula+=' × '+Number((e.ratio*100).toFixed(6))+'%'}$('manualFormula').textContent=formula;$('manualPrice').textContent=r?'¥'+money(c.amount):'—';$('estimate').textContent=e.override!==null?'已使用调整金额；需填写调整原因。':r?'按当前资料自动计算':'';$('rulenote').textContent=r?.note||'';$('manualSave').disabled=!r;
 };
 populate=function(){estimate()};applyManualPolicy=function(){estimate()};
 reset=function(){editing=null;form.reset();$('formtitle').textContent='手动补录';$('manualAdvanced').open=false;autoVersion='';inputType='';estimate()};$('cancel').onclick=reset;
 form.oninput=e=>{if(['teacher','student','studentSignDate','manualCountry','manualDegree','manualPackage','manualMajor','manualType','project','qty','ratio','fullPaid','signupHours','signupProjects','paid'].includes(e.target.id)){$('override').value='';$('reason').value='';$('manualRuleMode').checked=false}if(e.target.id==='manualType'&&inputType!==e.target.value){inputType=e.target.value;$('manualRuleMode').checked=false;$('override').value='';$('reason').value='';$('qty').value=/软件|基础课|课时|思维|绘画|自产转介绍/.test(inputType)?'':'1'}estimate()};form.onchange=estimate;$('teacher').onchange=estimate;$('studentSignDate').onchange=estimate;$('version').onchange=estimate;$('rule').onchange=estimate;
 form.onsubmit=ev=>{ev.preventDefault();const x=formEntry();if(!x.teacher||!x.student||!x.rule)return toast('请补全老师、学生和价格方案');if(x.override!==null&&(!Number.isFinite(x.override)||x.override<0||!x.reason.trim()))return toast('调整金额需不小于0，并填写调整原因');if($('manualRuleMode').checked&&!x.manualSchemeReason)return toast('请填写手动指定价格方案的核对说明');const duplicate=state.entries.some(e=>e.id!==x.id&&e.teacher===x.teacher&&e.student===x.student&&e.rule===x.rule&&e.project===x.project);if(duplicate&&!confirm('存在相同老师、学生和项目的绩效记录（含其他月份），确认不是重复结算？'))return;x.id=editing||crypto.randomUUID();const before=state.entries;state.entries=editing?state.entries.map(e=>e.id===editing?x:e):[...state.entries,x];try{save()}catch(err){state.entries=before;return toast('保存失败：'+err.message)}reset();render();renderReview();toast('已保存，报表与工资汇总已更新')};
 editManualEntry=function(id){const e=state.entries.find(e=>e.id===id);if(!e)return;reset();editing=id;for(const key of ids)if($(key)&&!['version','rule'].includes(key))$(key).value=e[key]??e.raw?.[key]??'';$('studentSignDate').value=StaffVersionPolicy.date(e.signDate||e.raw?.signDate)||'';const raw=e.raw||{};for(const [id,key]of [['manualCountry','country'],['manualDegree','degree'],['manualPackage','package'],['manualMajor','major']])$(id).value=raw[key]||'';$('manualType').value=e.manualInputType||raw.type||ruleBy(e.rule)?.item||'';inputType=$('manualType').value;$('manualPackage').value=e.manualInputPackage||raw.package||'';if(!e.raw||e.manualRule){$('manualRuleMode').checked=true;$('manualAdvanced').open=true;$('manualRuleReason').value=e.manualSchemeReason||'原手动补录记录'}autoVersion='';rulesFor(e.version,e.rule);$('formtitle').textContent='编辑补录记录';estimate();$('entries').scrollIntoView({behavior:'smooth',block:'start'})};
 const beforeRefresh=refreshCampusState;refreshCampusState=function(){beforeRefresh();reset()};
 $('entryform').previousElementSibling.textContent='填写学生、老师、套餐及产出后自动计费。';
 estimate();
})();
